import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.ArrayDeque;
import java.util.Queue;

public class Main {
    static int n;
    static ArrayList<Integer>[] adj;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        if (line == null) return;
        while (line.trim().isEmpty()) {
            line = reader.readLine();
            if (line == null) return;
        }

        n = Integer.parseInt(line.trim());
        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < n - 1; i++) {
            line = reader.readLine();
            while (line != null && line.trim().isEmpty()) {
                line = reader.readLine();
            }
            if (line == null) break;
            StringTokenizer st = new StringTokenizer(line);
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            adj[u].add(v);
            adj[v].add(u);
        }

        // 1. Encontrar o nó mais distante do nó 1
        int[] dist1 = new int[n + 1];
        int[] parent1 = new int[n + 1];
        int nodeA = bfs(1, dist1, parent1);

        // 2. Encontrar o nó mais distante de nodeA
        int[] distA = new int[n + 1];
        int[] parentA = new int[n + 1];
        int nodeB = bfs(nodeA, distA, parentA);

        int diameter = distA[nodeB];

        // Reconstruir o caminho de nodeA até nodeB
        int[] path = new int[diameter + 1];
        int curr = nodeB;
        for (int i = diameter; i >= 0; i--) {
            path[i] = curr;
            curr = parentA[curr];
        }

        long count = 0;

        if (diameter % 2 == 0) {
            // Centro único
            int center = path[diameter / 2];
            int k = diameter / 2;

            long sum = 0;
            long sumSq = 0;

            for (int neighbor : adj[center]) {
                long c = countAtDistance(neighbor, center, k - 1);
                sum += c;
                sumSq += c * c;
            }

            count = (sum * sum - sumSq) / 2;
        } else {
            // Aresta central
            int c1 = path[diameter / 2];
            int c2 = path[diameter / 2 + 1];
            int k = diameter / 2;

            long cnt1 = countAtDistance(c1, c2, k);
            long cnt2 = countAtDistance(c2, c1, k);

            count = cnt1 * cnt2;
        }

        System.out.println(diameter + 1);
        System.out.println(count);
    }

    static int bfs(int start, int[] dist, int[] parent) {
        Arrays.fill(dist, -1);
        Queue<Integer> q = new ArrayDeque<>();

        dist[start] = 0;
        parent[start] = 0;
        q.add(start);

        int farthestNode = start;

        while (!q.isEmpty()) {
            int u = q.poll();
            if (dist[u] > dist[farthestNode]) {
                farthestNode = u;
            }

            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.add(v);
                }
            }
        }

        return farthestNode;
    }

    static long countAtDistance(int start, int forbidden, int targetDist) {
        if (targetDist < 0) return 0;
        if (targetDist == 0) return 1;

        Queue<Integer> q = new ArrayDeque<>();
        Queue<Integer> d = new ArrayDeque<>();
        boolean[] visited = new boolean[n + 1];

        visited[forbidden] = true;
        visited[start] = true;

        q.add(start);
        d.add(0);

        long count = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            int dist = d.poll();

            if (dist == targetDist) {
                count++;
                continue;
            }

            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.add(v);
                    d.add(dist + 1);
                }
            }
        }

        return count;
    }
}
